package com.wms.model.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
@Entity @Table(name="purchase_requests") public class PurchaseRequest extends AuditableEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=60) private String requestNo; @Column(nullable=false,length=20) private String status="DRAFT"; @Column(nullable=false,length=20) private String source="MANUAL"; @ManyToOne(optional=false,fetch=FetchType.LAZY) private Warehouse warehouse; @ManyToOne(fetch=FetchType.LAZY) private BusinessPartner supplier; private LocalDate requiredDate; private String applicant; private String reviewer; private String reviewRemark; private String remark;
 @OneToMany(mappedBy="request",cascade=CascadeType.ALL,orphanRemoval=true) private List<PurchaseRequestLine> lines=new ArrayList<>();
 public Long getId(){return id;} public String getRequestNo(){return requestNo;} public void setRequestNo(String v){requestNo=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getSource(){return source;} public void setSource(String v){source=v;} public Warehouse getWarehouse(){return warehouse;} public void setWarehouse(Warehouse v){warehouse=v;} public BusinessPartner getSupplier(){return supplier;} public void setSupplier(BusinessPartner v){supplier=v;} public LocalDate getRequiredDate(){return requiredDate;} public void setRequiredDate(LocalDate v){requiredDate=v;} public String getApplicant(){return applicant;} public void setApplicant(String v){applicant=v;} public String getReviewer(){return reviewer;} public void setReviewer(String v){reviewer=v;} public String getReviewRemark(){return reviewRemark;} public void setReviewRemark(String v){reviewRemark=v;} public String getRemark(){return remark;} public void setRemark(String v){remark=v;} public List<PurchaseRequestLine> getLines(){return lines;} public void replaceLines(List<PurchaseRequestLine> values){lines.clear();values.forEach(x->{x.setRequest(this);lines.add(x);});}
}
